insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-stack-top-retarget-s655','decision','Retarget a stack''s top to main before merging through it','S655 conductor: before merging a stack through its top, retarget the top''s base to main; confirm any merge by git log origin/main, never by the PR''s merged flag. Why: #3330''s base was its stacked branch, so it merged there at 05:04Z and #3327 closed unmerged; the meter never reached main until #3351. Amends d-merge-stack-tops-s654.',array['conductor','branch-policy','decision'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15'),
('d-classifier-asks-what-fits-s655','decision','cer-classify asks the front run of titles that fits $40','S655, #3351 c0cf44b9: cer-classify asks the longest front run of titles that fits $40, simulated post by post at three attempts a post; the rest waits for the next night, green with a warning; red only when no chunk fits. At 173,548 characters of rules a post is $5.74: 6 of 27 chunks, 90 of 400 titles, $34.46. Refusing the whole batch past 390 titles would have stalled the queue.',array['governance','cost','cer-procedures','decision'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15'),
('d-chat-priced-at-dearest-accepting-model-s655','decision','cpl-chat priced at the dearest model that accepts its request','S655, #3351: cpl-chat is priced at $5/$25 (Opus 5, 4.8 and 4.7 accept Sierra''s request shape), $0.7048 an answer: smoke $23.96, preflight $7.05, health $1.41, ask $0.70; the A/B capped at 56 answers ($39.47), the 70-answer run refused. News harvest bound: 9 calls, $27.27. CALL_MAX_USD 1.55. Loosens when the functions return usage.',array['governance','cost','sierra','decision'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15'),
('p-3330-merged-into-stack-base-s655','pitfall','A PR''s merged flag said #3330 landed; it had not reached main','S655: handoff 655 said #3330 merged (5a4a9c68). Its base was claude/extraction-gate-always-s653, so it merged into that branch at 05:04Z and #3327 closed unmerged; the gates and kb/_spend_meter.py never reached main. Found at 06:21Z when the card 10 worker found no meter. #3351 relanded it; #3350 closed with a pointer.',array['conductor','branch-policy','pitfall'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15'),
('p-handoff-count-not-derivable-s655','pitfall','A handoff''s expected count with no file behind it cannot gate a write','S655: handoff 655 expected the course-id rescore to change 66 scores and one status; the six reconciles changed 189 and 4, and nobody could derive the 66 from files. A handoff''s count with no file behind it cannot gate a write; the reconcile''s own count and a second reader''s classification do.',array['program-requirements','rescore','conductor','pitfall'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15'),
('p-apply-edit-refused-by-permission-check-s655','pitfall','The permission check refused a worker''s .apply edit','S655: the Honors step 2 worker''s edit to kb/migrations/.apply was refused by the permission check; the brief had lifted the limit in words and the harness had not. A denial is a hold: the conductor did not make the edit for the worker. An apply by a push of .apply needs a session where that edit is permitted. Nothing applied; Sam notified about 07:31Z.',array['conductor','commons','honors','pitfall'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15'),
('p-reconcile-from-filed-pages-empties-holds-s655','pitfall','Reconcile from filed pages empties holds and rewrites sources','S655, #3352: the reconcile-from-filed-pages route emptied both hold lists, rewrote sources.json for records it did not rescore and dropped the arithmetic.rescored marker; it also rescored 26 records against pages main holds as wrong and re-passed American River 07206 (a held false pass). Fixed by restoring from main; the reader code is not fixed yet.',array['program-requirements','rescore','pitfall'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15'),
('riverside-city-capture-240-of-268-s655','fact','Riverside City capture: 240 of 268 on their own pages','S655: run 43670221611 (main 3ec83566) filed capture_preview.json f3b80958. Of 268 programs: sitemap_page 205 to 240, page_claimed 40 to 9, not_found 17 to 13, no_closed_list 6. 35 of 41 transfer degrees claim their own page; six stay page_claimed, their pages held by area-of-emphasis degrees (18108 to 18114), Chemistry 38838 or American Studies 31163. curriQunet colleges may capture again.',array['program-requirements','riverside-city','fact'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15'),
('santa-ana-objectives-1362-s655','fact','Santa Ana''s course objectives loaded: 1,362 rows','S655, #3344 534a415c: Santa Ana''s objectives reread (step 1 of objectives_reread_plan) loaded by run 43684986821: posted 1,362, inserted 1,362, kept 0, skipped 7, held back 1,366 SLO rows; receipt kb/receipts/course_outcomes_sac_43684986821.json. Live read: 1,362 objective rows from id 23508; course_outcomes total 24,301.',array['program-requirements','course-outcomes','fact'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15'),
('honors-step2-ready-held-s655','fact','Honors step 2 is ready and held: 380 rows','S655: #3315 merged as a plan (f90be0d6): 382 rows, step 2 writes 380 under honors-rows-s653@bot, rows md5 29667c07, 129 mints, 179 rows with the mint held. Second reader: apply (rollback 91/91). Live 07:28:57Z: 0 rows under the cohort, 0 person-saved rows since the 06:19:03Z sync. --check passed 07:29Z; the .apply edit was refused, so nothing applied.',array['commons','honors','fact'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15'),
('rescore-course-id-wave-s655','fact','The course-id rescore at six colleges','S655, #3352 (open): six rereads 08:50Z-09:03Z replaced 159 rows, 0 held, 0 absent: Diablo Valley 29, Barstow 4, American River 38, CCSF 42, Riverside City 38, Santiago Canyon 8; receipts with before-values on the branch. American River 12189, 12190 and Diablo Valley 37558 go fail to pass, none falls. 27 records restored from main first. Next: display build, COBIx spot-check, Diablo Valley first.',array['program-requirements','rescore','fact'],'proposed','S655 checkpoint; docs/session_656_handoff.md and the lane files',null,null,'SkyCurlew (S655)',date '2026-11-15')
